"""openhands `execute_bash` for the swegemma sandbox (generated by build_openhands_skill.py).

Runs the command in a fresh `bash -c` in the workspace, with stderr merged into stdout and stdin closed, and
prints the result the way OpenHands' execute_bash observations read in the CoderForge data: the output (always
ending in a newline), then
    [The command completed with exit code N.]
    [Current working directory: DIR]
    [Command finished with exit code N]
and the whole text cut to 30000 chars as the first and last 15000 with
"\n[... Observation truncated due to length ...]\n" between them. OpenHands' "[Python interpreter: ...]" line is
left out, because its path differs between environments. Jobs the command leaves in the background are killed.
"""
import os
import re
import shlex
import signal
import subprocess
import sys
import tempfile

VIRTUAL_ROOT = '/workspace'
MAX_CHARS = 30000
TRUNCATED = '\n[... Observation truncated due to length ...]\n'
DEFAULT_TIMEOUT, MAX_TIMEOUT = 280, 290  # ADK stops the script itself after 300 s


def _wrapper_path():
    """ADK runs `python3 <workspace>/.adk_exec_<id>.py`, which then chdirs to a temp dir."""
    for arg in getattr(sys, 'orig_argv', [])[1:]:
        if os.path.basename(arg).startswith('.adk_exec_') and arg.endswith('.py'):
            return os.path.abspath(arg)
    return None


def truncate(text):
    if len(text) <= MAX_CHARS:
        return text
    half = MAX_CHARS // 2
    return text[:half] + TRUNCATED + text[-half:]


def _parse_args(argv):
    out = {}
    for i in range(0, len(argv) - 1, 2):
        if argv[i].startswith('--'):
            out[argv[i][2:]] = argv[i + 1]
    return out


def main():
    wrapper = _wrapper_path()
    real = os.path.dirname(wrapper) if wrapper else os.environ.get('OH_BASH_WORKSPACE', VIRTUAL_ROOT)
    if wrapper:
        # The wrapper sits in the workspace while this runs; `git status` or `ls -a` must not show it.
        try:
            os.remove(wrapper)
        except OSError:
            pass
    args = _parse_args(sys.argv[1:])
    command = args.get('command')
    if command is None:
        sys.stdout.write('ERROR:\nParameter `command` is required. Pass args as {"command": "..."}.')
        return
    try:
        timeout = min(float(args.get('timeout') or DEFAULT_TIMEOUT), MAX_TIMEOUT)
    except ValueError:
        timeout = DEFAULT_TIMEOUT
    if real != VIRTUAL_ROOT:  # local subprocess sandbox: the repository is not at /workspace
        command = re.sub(r'(?<![\w.-])/workspace(?![\w.-])', lambda m: real, command)
    fd, cwd_file = tempfile.mkstemp(prefix='oh_bash_cwd_')
    os.close(fd)
    script = f"trap 'pwd > {shlex.quote(cwd_file)}' EXIT\n{command}"
    timed_out = False
    with tempfile.TemporaryFile() as out:
        proc = subprocess.Popen(['/bin/bash', '-c', script], cwd=real, stdin=subprocess.DEVNULL, stdout=out,
                                stderr=subprocess.STDOUT, start_new_session=True)
        try:
            rc = proc.wait(timeout=timeout)
        except subprocess.TimeoutExpired:
            timed_out, rc = True, -1
        try:
            os.killpg(proc.pid, signal.SIGKILL)
        except ProcessLookupError:
            pass
        proc.wait()
        out.seek(0)
        text = out.read().decode('utf-8', errors='replace')
    if rc < -1:
        rc = 128 - rc  # killed by a signal, reported as the shell would
    with open(cwd_file) as f:
        cwd = f.read().strip() or real
    os.remove(cwd_file)
    if real != VIRTUAL_ROOT:
        text = text.replace(real, VIRTUAL_ROOT)
        cwd = cwd.replace(real, VIRTUAL_ROOT)
    if not text.endswith('\n'):
        text += '\n'
    if timed_out:
        text += f'[The command timed out after {timeout:g} seconds and was stopped.]\n'
    else:
        text += f'[The command completed with exit code {rc}.]\n'
    text += f'[Current working directory: {cwd}]\n[Command finished with exit code {rc}]'
    sys.stdout.write(truncate(text))


if __name__ == '__main__':
    main()
